contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We test that for a chosen log method, calling it from this contract yields a return boolean
    // equal to c.approvedToLog(address(this)) observed immediately before the call.
    // We pick one log function that takes several params: logRedemptionRequested.
    function run(address requester, bytes32 digest, uint256 utxoSize, bytes calldata redeemerOutputScript, uint256 requestedFee, bytes calldata outpoint) public payable {
        // no precondition on parameters
        // observe whether this contract is currently approved to log
        bool beforeApproved = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        // perform the call that may or may not revert; functions in C return bool and do not revert
        bool returned;
        bool r = c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            // If it reverts (unexpected), treat as returned == false for the invariant comparison
            returned = false;
        } else {
            returned = r;
        }

        // The general rule: the returned bool must equal the observed approvedToLog status
        assert(returned == beforeApproved);
    }

    receive() external payable {}
}

