    }

    function _run(address requester, bytes32 digest, uint256 utxoSize, bytes memory redeemerOutputScript, uint256 requestedFee, bytes memory outpoint) internal {
        bool beforeApproved;
        try c.approvedToLog(address(this)) returns (bool __r) { beforeApproved = __r; } catch { return; }
        bool returned;
        try c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint) returns (bool r) {
            returned = r;
        } catch {
            // If it reverts (unexpected), treat as returned == false for the invariant comparison
            returned = false;
        }
        assertTrue(returned == beforeApproved);
    }

